"""Render BASELINES.md from baselines_results.json (every number comes from the json, nothing is typed by hand).

    python -m dataset_v2.render_baselines_md [--results baselines_results.json] [--out BASELINES.md]
"""
import argparse
import json
from pathlib import Path

from .classes import CLASSES

HERE = Path(__file__).parent


def _ci(c):
    return f"[{c[0]:.3f}, {c[1]:.3f}]"


def render(r):
    models = list(r["models"])
    L = ["# Baselines (generated)", "",
         "Generated by `python -m dataset_v2.render_baselines_md` from `baselines_results.json` (written by "
         "`python -m dataset_v2.baselines`). All numbers below were computed on the same `manifest.csv` / `splits.csv` "
         f"(sha256 {r['inputs_sha256']['manifest.csv'][:12]} / {r['inputs_sha256']['splits.csv'][:12]}), seed {r['seed']}.",
         "", f"Recordings: train {r['n']['train']}, val {r['n']['val']}, test {r['n']['test']}. Features: the 64-step "
         f"series subsampled to {r['feat_len']} steps, {r['n_features']} features, standardised on train. Hyper-parameter "
         "chosen on val macro-F1 only; test scored once per model. Grids: "
         + "; ".join(f"{k} {v}" for k, v in r["grids"].items()) + ". "
         f"Logistic regression max_iter {r['models']['logreg']['max_iter']} (iterations used: "
         f"{r['models']['logreg']['n_iter_reached']}).", "",
         "Note: the loose `Teleportation.json` and `Zoom.json` contain `class_name` LeftInfinity (see DATA_CARD).", "",
         "## Main result (full test split)", "",
         "| model | selected | optimum on grid edge | val macro-F1 | test accuracy | test macro-F1 |",
         "|---|---|---|---|---|---|"]
    for m in models:
        e = r["models"][m]
        L.append(f"| {m} | {e['selected']} | {e['selected_on_grid_edge']} | {e['val']['macro_f1']:.3f} | "
                 f"{e['test']['accuracy']:.3f} | {e['test']['macro_f1']:.3f} |")
    mc = r["majority_class_chance"]
    L += ["", f"Chance: majority class (train) test accuracy {mc['test_accuracy']:.3f}; uniform {mc['uniform_chance']:.3f}.", ""]

    L += ["## Effect of the (root) pseudo-session", "",
          "All 24 loose root files (one per class) form the pseudo-session `(root)` and the split puts that session "
          "in the TEST split (sessions are assigned whole). The files are single canonical examples recorded outside "
          "any session, so they are a different distribution from the session recordings, and two of them "
          "(`Teleportation.json`, `Zoom.json`) have content labelled LeftInfinity. Test metrics are therefore given "
          "with and without them.", "",
          "| model | test acc (all) | test macro-F1 (all) | test acc (excl. root) | test macro-F1 (excl. root) "
          "| acc on the 24 root files |",
          "|---|---|---|---|---|---|"]
    for m in models:
        e = r["models"][m]
        if "test_excl_root" in e:
            L.append(f"| {m} | {e['test']['accuracy']:.3f} | {e['test']['macro_f1']:.3f} | "
                     f"{e['test_excl_root']['accuracy']:.3f} | {e['test_excl_root']['macro_f1']:.3f} | "
                     f"{e['test_root_only']['accuracy']:.3f} (n={e['test_root_only']['n']}) |")
    L.append("")

    for key, title in (("bootstrap", "all test sessions"), ("bootstrap_excl_root", "excluding (root)")):
        b = r.get(key)
        if not b:
            continue
        L += [f"## Session-cluster bootstrap, 95% CI ({title})", "",
              f"{b['n_boot']} resamples of the {b['n_sessions']} test sessions with replacement (percentile interval; "
              "the same resamples for every model).", "", "| model | accuracy CI | macro-F1 CI |", "|---|---|---|"]
        for m, v in b["models"].items():
            L.append(f"| {m} | {_ci(v['accuracy_ci95'])} | {_ci(v['macro_f1_ci95'])} |")
        d = b.get("logreg_minus_lda")
        if d:
            L += ["", f"Paired difference logreg - lda: accuracy {_ci(d['accuracy_ci95'])}, macro-F1 {_ci(d['macro_f1_ci95'])}. "
                  + ("The interval excludes 0 for "
                     + ", ".join(n for n, f in (("accuracy", d["accuracy_differs"]), ("macro-F1", d["macro_f1_differs"])) if f)
                     + "." if (d["accuracy_differs"] or d["macro_f1_differs"]) else
                     "Both intervals contain 0: logreg and lda are not distinguishable on this test split, "
                     "so they are not ranked.")]
        L.append("")

    L += ["## Within-hand accuracy and hand-presence baseline", "",
          "The absent hand is zero-filled, so which hand was used (left / right / both) is trivially readable from the "
          "input. Within-hand accuracy restricts the prediction to the classes of the true hand group (11-way for left "
          "and right recordings, 2-way for Teleportation/Zoom), i.e. it removes the left-vs-right decision.", "",
          "| model | within-hand overall | left (11-way) | right (11-way) | both (2-way) "
          "| hand-group accuracy of the unrestricted prediction |",
          "|---|---|---|---|---|---|"]
    for m in models:
        w = r["models"][m]["within_hand"]
        L.append(f"| {m} | {w['overall']:.3f} | {w['left']['accuracy']:.3f} (n={w['left']['n']}) | "
                 f"{w['right']['accuracy']:.3f} (n={w['right']['n']}) | {w['both']['accuracy']:.3f} (n={w['both']['n']}) | "
                 f"{w['hand_group_accuracy_of_unrestricted_prediction']:.3f} |")
    h = r["hand_presence_baseline"]
    L += ["", f"Hand-presence-only baseline ({h['description']}): test accuracy {h['test']['accuracy']:.3f}, macro-F1 "
          f"{h['test']['macro_f1']:.3f} (presence agrees with the class hand for {h['presence_agrees_with_class_hand']:.3f} "
          "of the recordings). Any model has to beat this, not only the 1/24 chance level.", ""]

    a = r.get("ablation_local_pos_only")
    if a:
        L += ["## Ablation: local joint positions only (no root channels)", "",
              f"{a['n_features']} features. Same protocol, reselected on val.", "",
              "| model | selected | val macro-F1 | test accuracy | test macro-F1 | test acc excl. root "
              "| within-hand overall |",
              "|---|---|---|---|---|---|---|"]
        for m, e in a["models"].items():
            ex = e.get("test_excl_root", {}).get("accuracy")
            L.append(f"| {m} | {e['selected']} | {e['val']['macro_f1']:.3f} | {e['test']['accuracy']:.3f} | "
                     f"{e['test']['macro_f1']:.3f} | {'n/a' if ex is None else format(ex, '.3f')} | "
                     f"{e['within_hand']['overall']:.3f} |")
        L.append("")

    L += ["## Per-class test recall (full test split)", "", "| class | " + " | ".join(models) + " |",
          "|---|" + "---|" * len(models)]
    for i, name in enumerate(CLASSES):
        L.append(f"| {name} | " + " | ".join(f"{r['models'][m]['test']['per_class_recall'][str(i)]:.2f}" for m in models) + " |")
    return "\n".join(L) + "\n"


def main(argv=None):
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--results", default=str(HERE / "baselines_results.json"))
    p.add_argument("--out", default=str(HERE / "BASELINES.md"))
    a = p.parse_args(argv)
    r = json.loads(Path(a.results).read_text(encoding="utf-8"))
    Path(a.out).write_text(render(r), encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
